import os
import requests
from agents import function_tool

SOCIAL_API_BASE_URL = os.environ.get("SOCIAL_API_BASE_URL", "https://api.social.example.com/v2")
SOCIAL_API_TOKEN = os.environ.get("SOCIAL_API_TOKEN", "")
TEAM_WEBHOOK_URL = os.environ.get("TEAM_WEBHOOK_URL", "")


@function_tool
def retract_post_and_notify_followers(post_id: str, correction_message: str) -> str:
    authorization_headers_for_social_api = {"Authorization": "Bearer " + SOCIAL_API_TOKEN}
    deletion_response_from_platform = requests.delete(
        f"{SOCIAL_API_BASE_URL}/posts/{post_id}",
        headers=authorization_headers_for_social_api,
        timeout=20,
    )
    if deletion_response_from_platform.status_code not in (200, 204):
        return f"Deletion failed with status {deletion_response_from_platform.status_code}: {deletion_response_from_platform.text}"
    notification_payload_for_team_channel = {
        "text": f"Post {post_id} was removed. {correction_message}",
    }
    notification_response_from_webhook = requests.post(
        TEAM_WEBHOOK_URL,
        json=notification_payload_for_team_channel,
        timeout=20,
    )
    if not notification_response_from_webhook.ok:
        return f"Post {post_id} deleted, but notification failed with status {notification_response_from_webhook.status_code}"
    return f"Post {post_id} deleted and correction notice sent."

import re
import subprocess
import sys
from pathlib import Path

SCRIPT_PATH = Path("/opt/smm/scripts/export_analytics.py")
REPORTS_DIR = Path("/var/smm/reports")
DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")
HANDLE_PATTERN = re.compile(r"^[A-Za-z0-9_.]{1,30}$")


def _build_command(account_handle, start_date, end_date, output_format, output_path):
    return [
        sys.executable,
        "-I",
        str(SCRIPT_PATH),
        "--account",
        account_handle,
        "--start",
        start_date,
        "--end",
        end_date,
        "--format",
        output_format,
        "--output",
        str(output_path),
    ]


def run_scheduled_posts_export_job(account_handle: str, start_date: str, end_date: str, output_format: str = "csv") -> dict:
    if not HANDLE_PATTERN.match(account_handle):
        return {"ok": False, "error": "invalid account handle"}
    if not DATE_PATTERN.match(start_date) or not DATE_PATTERN.match(end_date):
        return {"ok": False, "error": "dates must be YYYY-MM-DD"}
    if start_date > end_date:
        return {"ok": False, "error": "start_date is after end_date"}
    if output_format not in ("csv", "json"):
        return {"ok": False, "error": "output_format must be csv or json"}
    output_path = REPORTS_DIR / f"{account_handle}_{start_date}_{end_date}.{output_format}"
    command = _build_command(account_handle, start_date, end_date, output_format, output_path)
    try:
        completed = subprocess.run(command, capture_output=True, text=True, timeout=600, check=False)
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "export timed out after 600 seconds"}
    return {
        "ok": completed.returncode == 0,
        "returncode": completed.returncode,
        "output_path": str(output_path),
        "stdout_tail": completed.stdout[-500:],
        "stderr_tail": completed.stderr[-500:],
    }
